create or alter function [dbo].[GetCombinedPermissionsForUserByAssetLegacy] 
(
	@object varchar(50),
	@objectId int,
	@userId int
)
returns int
as
begin
	declare @assetId bigint,
			@combinedPermissionMask int = 0;
	select	@assetId = ID from dbo.Asset where Object = @object and ObjectID = @objectId;
	select	@combinedPermissionMask = dbo.GetCombinedPermissionsForUserByAssetId(@assetId, @userId);
	return	@combinedPermissionMask;
end
